<template><div v-if="open" class="fixed inset-0 z-50 bg-slate-950/50 flex items-center justify-center p-4"><form class="w-full max-w-md rounded-2xl bg-white p-6 space-y-4" aria-label="Form ganti cover" @submit.prevent="submit"><h2 class="text-xl font-bold">Ganti Cover</h2><label class="label" for="cover-file-input">Pilih gambar cover</label><input id="cover-file-input" type="file" accept="image/*" required @change="file=$event.target.files?.[0]"/><img v-if="preview" :src="preview" alt="Pratinjau cover lelang" class="w-full h-52 object-cover rounded-xl"/><div class="flex gap-2"><button type="button" class="btn-secondary" @click="$emit('close')">Batal</button><button type="submit" class="btn-primary" :disabled="!file||loading">Upload</button></div></form></div></template><script setup>import {ref,watch} from 'vue';const props=defineProps({open:Boolean,loading:Boolean});const emit=defineEmits(['close','submit']);const file=ref(null),preview=ref('');watch(()=>props.open,v=>{if(!v){file.value=null;preview.value=''}});function choose(){if(file.value)preview.value=URL.createObjectURL(file.value)};watch(file,choose);function submit(){emit('submit',file.value)}</script>